const sent=$input.item.json;
if(sent.error||!(sent.key?.id||sent.message?.key?.id))return null;
let context,reply;
try{context=$('Preparar contexto seguro').first().json;reply=$('Preparar menção individual').item.json;}catch{return null;}
let mode='default';
try{
 if($('AI Agent · intenção financeira').isExecuted){
  const raw=$('AI Agent · intenção financeira').first().json.output;
  const value=typeof raw==='string'?JSON.parse(raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'')):raw;
  if(value&&typeof value==='object'&&!Array.isArray(value)&&['audio','text','default'].includes(value.response_mode))mode=value.response_mode;
 }
}catch{}
if(mode==='text')return null;
let report=null;
try{if($('Confirmar preferência financeira').isExecuted)report=$('Confirmar preferência financeira').first().json;}catch{}
const automatic=report?.reportReady===true&&report.spokenReport===true&&typeof report.reportBody==='string'&&Boolean(report.reportBody.trim());
if(mode!=='audio'&&!automatic)return null;
const body=typeof reply.replyText==='string'?reply.replyText:'';
if(!context.user?.id||!context.messageId||!context.chatId||!body.trim()||body.length>5000)return null;
return {json:{userId:context.user.id,chatId:context.chatId,source_message_id:context.messageId,body,explicit_voice:mode==='audio'||report?.explicitVoice===true,responseMode:mode}};

const r=$input.item.json;if(r.ok!==true)return null;
const request=$('Autorizar resumo falado solicitado').item.json;
const base={voice_id:r.voice_id,voice_lease:r.voice_lease,userId:request.userId,chatId:request.chatId,sourceMessageId:request.source_message_id,audioReady:false};
const fail=()=>({json:{...base,speechReady:false,voiceOutcome:'failed',noticeAllowed:true}});
const small=['zero','um','dois','três','quatro','cinco','seis','sete','oito','nove','dez','onze','doze','treze','catorze','quinze','dezesseis','dezessete','dezoito','dezenove'];const tens=['','','vinte','trinta','quarenta','cinquenta','sessenta','setenta','oitenta','noventa'];const hundreds=['','cento','duzentos','trezentos','quatrocentos','quinhentos','seiscentos','setecentos','oitocentos','novecentos'];
function words(n){n=Math.trunc(n);if(n<0)return 'menos '+words(-n);if(n<20)return small[n];if(n<100)return tens[Math.floor(n/10)]+(n%10?' e '+words(n%10):'');if(n===100)return 'cem';if(n<1000)return hundreds[Math.floor(n/100)]+(n%100?' e '+words(n%100):'');if(n<1000000)return(Math.floor(n/1000)===1?'mil':words(Math.floor(n/1000))+' mil')+(n%1000?(n%1000<100||n%100===0?' e ':' ')+words(n%1000):'');return words(Math.floor(n/1000000))+(Math.floor(n/1000000)===1?' milhão':' milhões')+(n%1000000?' e '+words(n%1000000):'');}
function money(n){const c=Math.round(Math.abs(Number(n))*100);const whole=Math.floor(c/100),cent=c%100;return(Number(n)<0?'menos ':'')+words(whole)+(whole===1?' real':' reais')+(cent?' e '+words(cent)+(cent===1?' centavo':' centavos'):'');}

try{
 let text=typeof r.source?.body==='string'?r.source.body:'';
 text=text.replace(/@\d{7,}(?:@(?:s\.whatsapp\.net|g\.us))?/g,'').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu,'').replace(/[*_`#~]/g,'').replace(/[\r\n]+/g,'. ').replace(/\s+/g,' ').trim();
 text=text.replace(/(-?)R\$\s*(-?)(\d+(?:\.\d{3})*(?:,\d{1,2})?)/g,(_,s1,s2,n)=>money((s1||s2?-1:1)*Number(n.replace(/\./g,'').replace(',','.')))).replace(/(\d+)%/g,(_,n)=>words(Number(n))+' por cento');
 if(!text||/@\d/.test(text))return fail();
 if(text.length>1400){let cut=text.slice(0,1310);const stop=Math.max(cut.lastIndexOf('. '),cut.lastIndexOf('! '),cut.lastIndexOf('? '));cut=stop>900?cut.slice(0,stop+1):cut.slice(0,cut.lastIndexOf(' '));text=cut.trim()+' Os detalhes completos estão na mensagem de texto.';}
 if(!text||text.length>1400)return fail();
 const style=Number(r.speed)<1?'Warm and friendly Brazilian Portuguese, slightly slower pace, clear pronunciation':Number(r.speed)>1?'Warm and friendly Brazilian Portuguese, slightly faster pace, clear pronunciation':'Warm and friendly Brazilian Portuguese, natural calm pace, clear pronunciation';
 return {json:{...base,speechReady:true,voiceOutcome:'preparing',noticeAllowed:false,spokenText:text,ttsBody:{model:'gemini-3.8-flash-lite-tts',input:[{type:'user_input',content:[{type:'text',text,annotations:[{type:'speech_metadata',style}]}]}],response_format:{type:'audio'},generation_config:{speech_config:[{voice:'Kore'}]}}}};
}catch{return fail();}

const x=$('Preparar fala do Bot do Ni').item.json;
const r=$input.item.json;
let audioReady=false,audio='';
try{
 const audios=(Array.isArray(r.steps)?r.steps:[]).flatMap(s=>Array.isArray(s.content)?s.content:[]).filter(c=>c.type==='audio'&&typeof c.data==='string');
 const part=audios.at(-1);
 if(!r.error&&part&&/^[A-Za-z0-9+/]+={0,2}$/.test(part.data)&&part.data.length%4!==1){
  const b=Buffer.from(part.data,'base64');
  const canonical=b.toString('base64').replace(/=+$/,'')===part.data.replace(/=+$/,'');
  const wav=b.length>44&&b.toString('ascii',0,4)==='RIFF'&&b.toString('ascii',8,12)==='WAVE';
  const mp3=(b.toString('ascii',0,3)==='ID3'||(b[0]===255&&(b[1]&224)===224))&&b.length>1000;
  if(canonical&&(wav||mp3)&&b.length<5000000){audioReady=true;audio=part.data;}
 }
}catch{}
return {json:{voice_id:x.voice_id,voice_lease:x.voice_lease,userId:x.userId,chatId:x.chatId,sourceMessageId:x.sourceMessageId,audioReady,ttsAudio:audio,voiceOutcome:audioReady?'prepared':'failed',noticeAllowed:!audioReady}};

const x=$('Restaurar áudio autorizado').item.json,r=$input.item.json;
const messageId=r.key?.id||r.message?.key?.id;
const success=!r.error&&typeof messageId==='string'&&Boolean(messageId);
const voiceOutcome=success?'sent':'uncertain';
const state=$getWorkflowStaticData('global');
const previous=(Array.isArray(state.voiceOutcomes)?state.voiceOutcomes:[]).filter(v=>v&&typeof v==='object').map(v=>({at:v.at,sourceMessageId:v.sourceMessageId,voice_id:v.voice_id,outcome:v.outcome,...(typeof v.messageId==='string'?{messageId:v.messageId}:{})}));
state.voiceOutcomes=[...previous,{at:Date.now(),sourceMessageId:x.sourceMessageId,voice_id:x.voice_id,outcome:voiceOutcome,...(success?{messageId}:{})}].slice(-20);
return {json:{voice_id:x.voice_id,voice_lease:x.voice_lease,userId:x.userId,chatId:x.chatId,sourceMessageId:x.sourceMessageId,success,voiceOutcome,noticeAllowed:!success,...(success?{messageId}:{})}};

const x=$input.item.json;
if(!['sent','uncertain'].includes(x.voiceOutcome)){
 const state=$getWorkflowStaticData('global');
 const previous=(Array.isArray(state.voiceOutcomes)?state.voiceOutcomes:[]).filter(v=>v&&typeof v==='object').map(v=>({at:v.at,sourceMessageId:v.sourceMessageId,voice_id:v.voice_id,outcome:v.outcome,...(typeof v.messageId==='string'?{messageId:v.messageId}:{})}));
 state.voiceOutcomes=[...previous,{at:Date.now(),sourceMessageId:x.sourceMessageId,voice_id:x.voice_id,outcome:x.voiceOutcome}].slice(-20);
}
return {json:{voice_id:x.voice_id,voice_lease:x.voice_lease,userId:x.userId,chatId:x.chatId,sourceMessageId:x.sourceMessageId,success:x.success===true,voiceOutcome:x.voiceOutcome,noticeAllowed:x.noticeAllowed===true}};

const x=$('Preparar resultado seguro da voz').item.json;
const request=$('Autorizar resumo falado solicitado').item.json;
if(x.noticeAllowed!==true||x.success===true||x.voiceOutcome==='sent'||!request.chatId||x.chatId!==request.chatId)return null;
const replyText=x.voiceOutcome==='uncertain'
 ? 'A resposta está no texto acima. Não consegui confirmar a entrega do áudio e não vou reenviá-lo automaticamente.'
 : x.voiceOutcome==='not_authorized'
 ? 'A resposta continua disponível no texto acima. O áudio não foi enviado.'
 : 'A resposta está no texto acima. Não consegui preparar o áudio agora.';
return {json:{chatId:request.chatId,replyText}};
